/* Creates the next owner-approved 15 Engineering knowledge pages without
 * changing the frozen hierarchy or calculator behaviour. */
const fs = require("fs");
const path = require("path");
const root = __dirname;
const reviewDate = "30 August 2026";
const siteUrl = "https://industrialcalculation.com/";
const esc = (s) => String(s).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");
const slug = (s) => s.toLowerCase().replace(/[–—]/g, "-").replace(/&/g, "and").replace(/[^a-z0-9]+/g, "-").replace(/(^-|-$)/g, "");
const file = (route) => path.join(root, ...route.split("/"));
const href = (from, to) => path.posix.relative(path.posix.dirname(from), to) || "index.html";
const canonical = (route) => `${siteUrl}${route.replace(/index\.html$/, "")}`;
const list = (items) => `<ul>${items.map((item) => `<li>${esc(item)}</li>`).join("")}</ul>`;
const bookSets = {
  fluid: ["Munson, B. R., Okiishi, T. H., Huebsch, W. W. and Rothmayer, A. P. <em>Fundamentals of Fluid Mechanics</em>. 9th ed. Wiley. 2021.", "Fox, R. W., McDonald, A. T., Pritchard, P. J. and Leylegian, J. C. <em>Fox and McDonald’s Introduction to Fluid Mechanics</em>. 10th ed. Wiley. 2020."],
  thermal: ["Incropera, F. P., DeWitt, D. P., Bergman, T. L. and Lavine, A. S. <em>Fundamentals of Heat and Mass Transfer</em>. 8th ed. Wiley. 2017.", "Çengel, Y. A. and Ghajar, A. J. <em>Heat and Mass Transfer: Fundamentals and Applications</em>. 6th ed. McGraw Hill. 2020."]
};
const fluidL2 = "engineering/fluid-mechanics-piping-pumps-fans-ducts/index.html";
const thermalL2 = "engineering/thermal-engineering-and-boilers/index.html";
const l2Slug = (l2) => l2 === "Fluid Mechanics, Piping, Pumps, Fans and Ducts" ? "fluid-mechanics-piping-pumps-fans-ducts" : slug(l2);
const newRoute = (l2, l3, l4, title) => `engineering/${l2}/${l3}/${slug(l4)}/${slug(title)}/index.html`;
const topic = (id, l2, l3, l4, title, summary, principle, formulae, terms, factors, assumptions, method, example, apps, mistakes, faqs, family, calculator) => ({ id, l2, l3, l4, title, summary, principle, formulae, terms, factors, assumptions, method, example, apps, mistakes, faqs, family, calculator, route: newRoute(l2Slug(l2), slug(l3), l4, title), parent: `engineering/${l2Slug(l2)}/${slug(l3)}/index.html`, image: family === "fluid" ? "assets/illustrations/l2-fluid-mechanics-piping-system-v1.png" : "assets/illustrations/l2-thermal-engineering-boiler-system-v1.png" });

const pages = [
  topic("ICH-ENG-004", "Fluid Mechanics, Piping, Pumps, Fans and Ducts", "Fluid Properties", "Viscosity", "Dynamic and Kinematic Viscosity", "Dynamic viscosity describes a fluid’s resistance to shear, while kinematic viscosity relates that resistance to density. Both properties affect pressure loss, flow regime, pumping and heat-transfer calculations.", "A fluid shears when adjacent layers move at different velocities. Dynamic viscosity links shear stress to velocity gradient; kinematic viscosity is dynamic viscosity divided by density and is often used in fluid-flow correlations.", [["Newton’s law of viscosity", "τ = μ (du/dy)", "Shear stress τ is proportional to velocity gradient du/dy for a Newtonian fluid."], ["Kinematic viscosity", "ν = μ / ρ", "Use dynamic viscosity μ and density ρ at the same temperature and pressure."]], [["Dynamic viscosity, μ", "Resistance to shear; SI unit Pa·s."], ["Kinematic viscosity, ν", "Dynamic viscosity divided by density; SI unit m²/s."], ["Newtonian fluid", "Fluid with viscosity that is substantially independent of shear rate."], ["Temperature basis", "The stated temperature at which property data apply."]], ["Temperature, which can substantially alter liquid viscosity.", "Composition, concentration and contamination.", "Shear rate for non-Newtonian materials such as slurries or polymer solutions."], ["Properties represent the actual fluid composition and temperature.", "The Newtonian approximation is suitable where it is used.", "The selected viscosity form matches the engineering method."], ["Define fluid composition, temperature and pressure.", "Obtain a traceable dynamic or kinematic viscosity value at that condition.", "Select the characteristic velocity and geometry for the planned calculation.", "Use the property consistently in Reynolds-number, loss or heat-transfer methods.", "Check whether non-Newtonian behaviour or temperature variation requires a specialised method."], "For a liquid line, obtain viscosity at the operating temperature before calculating Reynolds number and friction factor. A room-temperature property should not be substituted for a heated or cooled process stream.", ["Pipe and duct pressure-loss assessment.", "Pump and line sizing screening.", "Reynolds-number and friction-factor selection.", "Heat-exchanger and mixing calculations."], ["Using a viscosity value at the wrong temperature.", "Confusing dynamic and kinematic viscosity.", "Assuming all fluids are Newtonian.", "Mixing units such as cP, Pa·s and m²/s without conversion."], [["Do gases have viscosity?", "Yes. Gas viscosity also affects flow and heat-transfer behaviour, although its temperature trend differs from many liquids."], ["Which viscosity should be used for Reynolds number?", "Use either dynamic viscosity with density or kinematic viscosity directly, but keep all data at the same condition."], ["Why is viscosity important for pumping?", "It affects friction loss, pump performance and the suitability of correlations used for the system."]], "fluid", "pipe-flow-calculator.html"),
  topic("ICH-ENG-007", "Fluid Mechanics, Piping, Pumps, Fans and Ducts", "Fluid Flow Principles", "Pressure and Head", "Pressure Head, Velocity Head and Total Head", "Pressure head, velocity head and elevation head express different forms of fluid energy on a common head basis. Their combination is used to interpret hydraulic and duct-system energy balances.", "Pressure, velocity and elevation can each be represented as an equivalent fluid-column height. Total head is the consistent sum of the applicable terms at a stated location, before losses and machinery effects are added.", [["Pressure head", "p / (ρg)", "Pressure expressed as fluid height."], ["Velocity head", "v² / (2g)", "Kinetic-energy term based on mean velocity."], ["Total head", "H = p/(ρg) + v²/(2g) + z", "State the datum and include only compatible conditions."]], [["Static pressure", "Pressure measured independently of flow direction."], ["Velocity", "Mean flow velocity for the selected cross-section."], ["Elevation head, z", "Height relative to a clearly chosen datum."], ["Head loss", "Energy dissipated by friction and local disturbances."]], ["Fluid density and specific gravity.", "Flow area and resulting mean velocity.", "Elevation of the selected measurement points."], ["The fluid can be represented by the selected density.", "Velocity is a suitable section-average velocity.", "All terms use one consistent datum and unit system."], ["Set the two physical locations and the elevation datum.", "Record pressure, flow rate, geometry and fluid properties at both locations.", "Convert flow rate to mean velocity where required.", "Express terms as head and include pump, turbine and loss terms.", "Check signs and confirm that pressure basis is correct."], "Compare two pipe sections at different elevations and diameters. Express their measured pressures as head, calculate each velocity head, and retain friction loss rather than assuming that total head is unchanged.", ["Pump-system head calculations.", "Pressure-tap interpretation.", "Duct and pipe energy balances.", "Flow-meter and nozzle concepts."], ["Adding pressure in Pa directly to height in m.", "Ignoring density changes for gases or varying-temperature fluids.", "Omitting friction and fitting losses.", "Using gauge and absolute pressures inconsistently."], [["Is total head always constant?", "Only in an ideal case. Practical systems include loss, pump and turbine terms."], ["Why use head instead of pressure?", "Head gives pressure, velocity and elevation effects a common energy-per-unit-weight basis."], ["Does velocity head matter in a large pipe?", "It may be small, but should be assessed rather than assumed away."]], "fluid", "pipe-flow-calculator.html"),
  topic("ICH-ENG-009", "Fluid Mechanics, Piping, Pumps, Fans and Ducts", "Piping Systems", "Pipe Flow", "Pipe Friction Loss and Darcy-Weisbach Equation", "The Darcy-Weisbach equation estimates major friction loss in a pipe from length, diameter, velocity, density and friction factor. It is a central relationship for preliminary pipe-system design.", "Wall friction converts mechanical energy into heat as fluid flows through a pipe. The Darcy friction factor represents the effect of Reynolds number and relative roughness for the selected flow condition.", [["Darcy-Weisbach equation", "hƒ = f (L/D) (v²/2g)", "Head loss hƒ depends on Darcy factor f, length L, inside diameter D and mean velocity v."], ["Pressure-drop form", "Δp = ρg hƒ", "Use density at the operating condition to convert head loss to pressure drop."]], [["Darcy friction factor, f", "Dimensionless factor used in the Darcy-Weisbach equation."], ["Relative roughness", "Internal roughness divided by inside diameter."], ["Major loss", "Distributed loss over straight pipe length."], ["Inside diameter", "Actual bore used for velocity and L/D."]], ["Flow regime and Reynolds number.", "Pipe material, age and internal roughness.", "Inside diameter, straight length and actual flow rate."], ["The pipe is sufficiently straight for the distributed-loss model.", "Fluid properties and diameter correspond to the stated condition.", "Fittings and valves are added separately as local losses."], ["Define flow rate, fluid condition, pipe material and actual inside diameter.", "Calculate mean velocity and Reynolds number.", "Obtain a suitable Darcy friction factor from a documented method.", "Calculate major loss for each constant-diameter segment.", "Add local losses, elevation and equipment terms to complete the system balance."], "For a new liquid transfer line, split the route into constant-diameter segments, evaluate velocity and friction factor at operating flow, then add equivalent local losses before comparing the result with available pump head.", ["Preliminary pipe sizing.", "Pump head and system-curve development.", "Water, oil and utility-line pressure-loss estimates.", "Hydraulic troubleshooting."], ["Using nominal size instead of actual inside diameter.", "Confusing Darcy and Fanning friction factors.", "Ignoring fittings, valves and entrance/exit losses.", "Using a friction factor outside its Reynolds-number and roughness basis."], [["Does Darcy-Weisbach include fittings?", "No. Add local losses separately unless they have been converted to a documented equivalent length."], ["Can it be used for gases?", "It is often a starting point, but significant density change requires an appropriate compressible-flow method."], ["What is the friction factor based on?", "Typically Reynolds number and relative roughness for the selected pipe condition."]], "fluid", "pipe-flow-calculator.html"),
  topic("ICH-ENG-010", "Fluid Mechanics, Piping, Pumps, Fans and Ducts", "Piping Systems", "Pipe Losses", "Minor Losses in Pipes, Fittings and Valves", "Minor or local losses arise where fluid changes direction, area or flow pattern through fittings, valves, entrances, exits and other disturbances. They can be material to a short or complex piping system.", "A local disturbance creates separation, mixing and turbulence that dissipate energy. Its effect is commonly represented by a dimensionless loss coefficient or a documented equivalent length.", [["Local-loss equation", "hₘ = K (v²/2g)", "K is the loss coefficient for the stated fitting, geometry, opening position and flow basis."], ["Equivalent length", "Lₑ = K D / f", "Use only when the factor and diameter basis are compatible with the method."]], [["Loss coefficient, K", "Dimensionless coefficient for a local disturbance."], ["Equivalent length", "Straight-pipe length that represents a specified local loss."], ["Reference velocity", "Velocity basis used by the selected K value."], ["Local loss", "Energy loss at a discrete component or geometry change."]], ["Valve type and opening position.", "Fitting geometry, radius and connection detail.", "Reference velocity, flow regime and component condition."], ["Published K values match the actual geometry and velocity basis.", "Components are in the stated operating position.", "The system does not require a more detailed vendor or CFD assessment."], ["List every fitting, valve, entrance, exit and area change in the flow path.", "Identify the appropriate reference velocity for each component.", "Use documented coefficients or equivalent lengths from an applicable source.", "Calculate each local loss and add it to distributed friction loss.", "Check the result against measured behaviour or vendor data where available."], "A short pipe route with several elbows and a control valve may have local losses comparable with or greater than its straight-pipe loss. Calculate them individually rather than treating the line as straight pipe only.", ["Valve and fitting pressure-loss estimates.", "Pump-system curves.", "Duct transitions and branch connections.", "Troubleshooting high pressure drop."], ["Using a K value for a different valve type or opening.", "Applying one velocity to components with different diameters.", "Counting a fitting twice through both K and equivalent length.", "Ignoring partially closed control valves."], [["Why are they called minor losses?", "The name is traditional; they may dominate a short or complex system."], ["Can one K value fit every elbow?", "No. Radius, geometry, diameter and connection detail influence the result."], ["Are manufacturer data preferred?", "Yes, when they apply to the actual component and service."]], "fluid", "pipe-flow-calculator.html"),
  topic("ICH-ENG-011", "Fluid Mechanics, Piping, Pumps, Fans and Ducts", "Piping Systems", "Piping Design Basics", "Pipe Sizing: Engineering Inputs and Limitations", "Pipe sizing is a multi-input engineering decision that balances required flow, allowable velocity, pressure loss, pump head, material, erosion, noise, operating flexibility and maintainability.", "A suitable pipe size is not selected from flow rate alone. Diameter changes velocity, friction, capital cost, control behaviour and the capacity required from connected equipment.", [["Continuity relation", "Q = A v", "Flow Q, flow area A and mean velocity v must refer to the same condition."], ["Circular-pipe area", "A = πD²/4", "Use actual inside diameter D for hydraulic calculations."]], [["Design flow", "Normal, minimum, maximum and upset flow cases used for sizing."], ["Allowable pressure loss", "System energy loss permitted by process and equipment duties."], ["Velocity criterion", "Service-specific screening limit, not a universal rule."], ["Inside diameter", "Hydraulic bore after schedule, lining or corrosion effects."]], ["Fluid phase, viscosity, density and solids content.", "Required flow range and future capacity.", "Allowable pressure loss, erosion, noise and control needs."], ["The design basis identifies all credible operating cases.", "Velocity criteria are appropriate for the stated service.", "Mechanical, layout, support and code requirements are reviewed separately."], ["Define fluid, flow cases, temperature, pressure and solids or gas content.", "Establish allowable pressure loss and relevant service criteria.", "Screen candidate nominal sizes using actual inside diameters.", "Calculate velocity, major and local losses for the complete route.", "Coordinate pump head, control-valve authority, line class, supports and lifecycle requirements."], "For a process line with a normal flow and a future maximum flow, compare several candidate sizes. Reject a size only after assessing velocity, full system loss, equipment duty, controllability and practical line-class constraints.", ["Process and utility piping studies.", "Pump suction and discharge lines.", "Ventilation and gas-transfer lines.", "Preliminary project cost and layout screening."], ["Using a single generic velocity criterion.", "Sizing without the full route and fittings.", "Ignoring minimum-flow, cleaning, start-up or upset cases.", "Treating a hydraulic diameter result as a final mechanical line specification."], [["Is the lowest velocity always best?", "No. Oversizing can increase capital cost, reduce control quality and create other operational issues."], ["Can nominal pipe size be used directly?", "No. Use the actual inside diameter for hydraulic calculations."], ["Who approves final pipe size?", "Final selection requires coordinated process, mechanical, piping, control and project review."]], "fluid", "pipe-flow-calculator.html"),
  topic("ICH-ENG-012", "Fluid Mechanics, Piping, Pumps, Fans and Ducts", "Pumps", "Centrifugal Pumps", "Centrifugal Pump Working Principle", "A centrifugal pump transfers energy to liquid by rotating an impeller, then converting part of the resulting velocity into pressure in the casing or diffuser. Its duty depends on pump geometry, speed, liquid properties and the connected system.", "Liquid enters near the impeller eye and is accelerated by rotating blades. The casing, volute or diffuser recovers pressure from velocity, while the system curve determines the actual operating point.", [["Hydraulic power", "Pₕ = ρ g Q H", "Hydraulic power depends on density, flow Q and differential head H."], ["Pump efficiency", "η = Pₕ / Pshaft", "Efficiency relates delivered hydraulic power to shaft power on a stated basis."]], [["Impeller", "Rotating element that transfers energy to the liquid."], ["Volute or diffuser", "Stationary passage that recovers pressure from velocity."], ["Head", "Energy added per unit weight of liquid."], ["Operating point", "Intersection of pump and system curves."]], ["Impeller diameter and rotational speed.", "Liquid density, viscosity and vapour-pressure behaviour.", "System resistance and static head."], ["The pump is properly primed and operates with adequate suction conditions.", "The pump curve is valid for the installed impeller and speed.", "The fluid is compatible with wetted materials and seals."], ["Define required duty points and liquid properties.", "Select a pump family capable of the flow and head range.", "Compare the system curve with the applicable pump curve.", "Check NPSH, efficiency, power, control range and minimum-flow needs.", "Confirm materials, sealing, motor and installation details with the supplier."], "For a transfer system, construct a system curve from static head and losses, then identify the operating point on the vendor curve. Verify suction conditions and motor power before accepting the selection.", ["Water and utility transfer.", "Process-liquid circulation.", "Cooling and wash-water systems.", "General industrial pumping."], ["Selecting from a pump curve without a system curve.", "Assuming rated duty equals installed duty.", "Ignoring NPSH, viscosity or minimum-flow limits.", "Using hydraulic power as motor input power without efficiency."], [["Can a centrifugal pump pump any liquid?", "No. Viscosity, solids, corrosion, vapour pressure and other properties affect suitability."], ["What sets the operating flow?", "The interaction of the pump curve and the actual system curve."], ["Why is priming important?", "Many centrifugal pumps need the casing and suction path filled to develop the intended liquid flow."]], "fluid", "pump-power-calculator.html"),
  topic("ICH-ENG-013", "Fluid Mechanics, Piping, Pumps, Fans and Ducts", "Pumps", "Centrifugal Pumps", "Pump Curves and System Curves", "Pump curves show how a specific pump responds to changes in flow, while system curves show the head required by the connected system. Their intersection identifies the expected operating point.", "A pump normally produces different head, efficiency, power and NPSH behaviour at different flows. A system requires static head plus flow-dependent losses; changing resistance or speed moves the operating point.", [["System head", "Hsystem = Hstatic + KQ²", "A simplified expression for systems dominated by turbulent-flow losses."], ["Affinity-law screening", "Q ∝ N; H ∝ N²; P ∝ N³", "Use only for geometrically similar operation within the pump maker’s stated range."]], [["Pump curve", "Vendor-tested relationship between flow and head for a stated pump and speed."], ["System curve", "Head requirement as a function of flow for the connected system."], ["Best efficiency point", "Operating region of highest tested efficiency."], ["Control curve", "Operating relationship after valve, speed or bypass control changes."]], ["Impeller diameter, speed and liquid density.", "Static head and system resistance.", "Valve position, parallel paths and pump arrangement."], ["Curves come from the correct pump, impeller diameter and rotational speed.", "The system curve contains the complete operating route.", "Parallel and series pumps are analysed with their correct combined curves."], ["Define all required operating cases.", "Build system curves from static head and loss calculations.", "Obtain vendor pump curves at the correct speed and impeller diameter.", "Locate candidate operating points and check efficiency, power and NPSH.", "Evaluate control, turndown, minimum flow and future cases."], "A control valve that throttles a pump changes the system resistance and moves the duty to lower flow. Compare this with speed control only using correct pump and system curves.", ["Pump selection and motor sizing.", "Variable-speed pump studies.", "Parallel and standby-pump evaluation.", "Commissioning and troubleshooting."], ["Treating the design flow as guaranteed without a system curve.", "Using affinity laws outside their valid range.", "Ignoring minimum flow or motor overload.", "Comparing curves at different impeller diameters or speeds."], [["What is the operating point?", "It is the intersection of the applicable pump and system curves."], ["Can a valve increase pump head?", "Throttling changes resistance and may move the point to higher pump head but lower flow."], ["Are pump curves universal?", "No. They are specific to a tested pump configuration, speed and liquid basis."]], "fluid", "pump-power-calculator.html"),
  topic("ICH-ENG-014", "Fluid Mechanics, Piping, Pumps, Fans and Ducts", "Pumps", "Pump Operation", "NPSH and Cavitation in Pumps", "Net positive suction head (NPSH) is a suction-condition measure used to assess the risk of liquid vapour formation in a pump. Cavitation can damage components, reduce performance and cause vibration.", "If local pressure near the impeller eye falls near or below liquid vapour pressure, vapour cavities can form. Their collapse in higher-pressure regions can create noise, vibration, surface damage and unstable pump operation.", [["Available NPSH", "NPSHₐ = (pabs,suction / ρg) + z − hL − (pv / ρg)", "Use a complete suction-side pressure, elevation, loss and vapour-pressure basis."], ["Selection check", "NPSHₐ > NPSHᵣ + margin", "Required margin is project- and pump-specific; use supplier guidance."]], [["NPSH available", "Suction head supplied by the installed system above vapour-pressure head."], ["NPSH required", "Pump-test-based value supplied for the pump at a stated condition."], ["Vapour pressure", "Pressure at which a liquid can form vapour at a given temperature."], ["Cavitation", "Formation and collapse of vapour cavities in a liquid-flow region."]], ["Liquid temperature and vapour pressure.", "Suction vessel level and atmospheric or vessel pressure.", "Suction-line losses, strainers and pump elevation."], ["Vapour pressure data match the actual liquid and temperature.", "Suction losses include fouling and operating valve positions.", "Vendor NPSH required applies to the intended pump and duty."], ["Define suction source pressure, minimum liquid level and liquid temperature.", "Calculate suction-line losses for the worst credible flow condition.", "Determine available NPSH using absolute-pressure and vapour-pressure terms.", "Compare with supplier NPSH required plus the approved margin.", "Review layout, submergence, suction piping and transient conditions."], "A pump that operates satisfactorily with cool water may cavitate when the same liquid is heated because vapour pressure rises. Recalculate NPSH at the highest operating temperature and lowest source level.", ["Pump suction design.", "Hot-water and volatile-liquid transfer.", "Troubleshooting noise, vibration and damage.", "Pump selection and layout review."], ["Using gauge pressure where absolute pressure is required.", "Ignoring strainer fouling or partially closed suction valves.", "Using NPSH required from a different pump speed or impeller.", "Assuming NPSH alone covers all suction transient and air-entrainment risks."], [["Does NPSH required equal a safety margin?", "No. It is a pump-test characteristic; a project margin is normally considered separately."], ["Can a larger suction pipe help?", "It can reduce suction loss, but it does not solve every suction or process limitation."], ["Is cavitation always visible?", "No. It may first appear as noise, vibration, performance loss or progressive damage."]], "fluid", "pump-power-calculator.html"),
  topic("ICH-ENG-016", "Fluid Mechanics, Piping, Pumps, Fans and Ducts", "Fans and Duct Systems", "Industrial Fans", "Fan Laws, Static Pressure and Fan Power", "Fan laws relate airflow, pressure and power to fan speed for similar conditions. Static pressure and system resistance are key to selecting and operating an industrial fan safely and efficiently.", "A fan produces a pressure rise that balances the connected duct-system resistance at an operating flow. Under similarity conditions, speed changes shift the fan performance curve and can strongly change absorbed power.", [["Fan-law screening", "Q ∝ N; Δp ∝ N²; P ∝ N³", "Use only for the same fan with comparable gas density and suitable operating range."], ["Air power", "Pair = Q Δp", "Use actual volume flow and pressure rise at the same condition."]], [["Static pressure", "Pressure available to overcome system resistance, after accounting for velocity effects as defined."], ["Total pressure", "Static and velocity-pressure terms on a consistent basis."], ["Fan curve", "Test-based fan performance relationship at a stated speed and density."], ["System curve", "Pressure requirement as a function of flow for the connected duct system."]], ["Fan speed, wheel geometry and drive arrangement.", "Gas density, temperature and composition.", "Duct resistance, dampers, filters and branch conditions."], ["The selected fan curve uses the applicable density and speed.", "The system curve includes filters, dampers, outlets and terminal devices.", "Speed changes remain within manufacturer limits."], ["Define required airflow, gas condition and pressure-loss basis.", "Build the system-resistance curve for each operating case.", "Use vendor fan curves corrected to the stated gas density.", "Check operating point, efficiency, motor power, noise and stability.", "Assess filter loading, control method and start-up cases."], "A modest speed increase can materially increase power because fan power varies approximately with the cube of speed. Confirm motor and drive capability before applying a speed change.", ["Process ventilation and dust collection.", "Combustion-air and induced-draft systems.", "Cooling-air and exhaust systems.", "Fan selection and variable-speed studies."], ["Applying fan laws across different gas densities without correction.", "Ignoring filter loading or damper position.", "Sizing a motor from air power without efficiency and service factor.", "Operating near unstable fan regions."], [["What is static pressure used for?", "It is commonly used to express the pressure available to overcome a duct system’s resistance."], ["Why does speed affect power so strongly?", "For similar fan operation, power approximately follows the cube of rotational speed."], ["Can one fan curve cover every installation?", "No. The operating point depends on the connected system and actual gas condition."]], "fluid", "duct-flow-calculator.html"),
  topic("ICH-ENG-018", "Fluid Mechanics, Piping, Pumps, Fans and Ducts", "Fans and Duct Systems", "Duct Systems › Duct Pressure Loss", "Duct Pressure Loss and System Resistance", "Duct-system resistance is the pressure loss created by straight duct, fittings, filters, terminals, dampers and equipment. It determines the pressure a fan must develop at the required airflow.", "Airflow through ducts causes distributed wall friction and local disturbance losses. Since many losses rise approximately with the square of flow in turbulent service, small airflow changes can significantly shift fan duty.", [["Duct loss relation", "Δp = f (L/Dh) (ρv²/2) + ΣK(ρv²/2)", "Use hydraulic diameter Dh and the correct local-loss velocity basis."], ["System relation", "Δp ≈ KQ²", "A screening form for a fixed duct configuration in turbulent-flow conditions."]], [["Hydraulic diameter", "Four times flow area divided by wetted perimeter for a non-circular duct."], ["Velocity pressure", "Dynamic pressure based on density and mean velocity."], ["Static pressure loss", "Pressure decrease associated with friction and local resistance."], ["System resistance", "Total pressure requirement of the connected duct path."]], ["Duct size, shape, roughness and straight length.", "Elbows, branches, transitions and dampers.", "Air density, flow, filter loading and terminal conditions."], ["Duct dimensions represent internal flow area.", "Loss coefficients match the actual fitting geometry.", "Air density is appropriate to the operating temperature and pressure."], ["Define airflow cases, air condition and full duct route.", "Calculate velocities in each section from its actual area.", "Estimate straight-duct friction and each local loss.", "Add filters, equipment, outlets and control-device losses.", "Develop a system curve and compare it with the selected fan curve."], "A clean filter and a loaded filter represent different duct-system curves. Evaluate both so the fan, motor and control arrangement accommodate expected loading.", ["Dust-collection and fume-extraction systems.", "HVAC and process ventilation.", "Combustion-air and exhaust ducts.", "Fan and damper selection."], ["Using one velocity for all branches.", "Ignoring filter loading and equipment pressure drop.", "Applying round-duct coefficients to an unrelated rectangular fitting.", "Treating a duct-pressure calculation as a final noise or structural design."], [["Why does a filter affect fan duty?", "Its pressure loss contributes to total system resistance and often rises as it loads."], ["Does larger duct always reduce system cost?", "It reduces velocity loss but may increase material, space and support cost."], ["What is hydraulic diameter for?", "It provides a characteristic dimension for non-circular duct flow calculations."]], "fluid", "duct-flow-calculator.html"),
  topic("ICH-ENG-020", "Thermal Engineering and Boilers", "Heat Transfer", "Convection", "Convective Heat Transfer and Heat Transfer Coefficient", "Convective heat transfer occurs between a surface and a moving or stationary fluid. The heat-transfer coefficient summarises the combined effect of fluid properties, velocity, geometry and flow regime for a stated condition.", "Fluid motion transports energy near a surface. Forced convection is driven by a fan, pump or other device; natural convection is driven by density differences caused by temperature variation.", [["Newton’s law of cooling", "Q̇ = h A (Ts − T∞)", "The coefficient h applies to a stated surface, fluid condition and temperature basis."], ["Heat flux", "qʺ = h (Ts − T∞)", "Heat flux is heat rate per surface area."]], [["Heat-transfer coefficient, h", "Convective conductance per area; SI unit W/(m²·K)."], ["Bulk fluid temperature", "Representative mixed-mean fluid temperature."], ["Film temperature", "A reference temperature often used for property evaluation."], ["Forced convection", "Convection enhanced by externally driven flow."]], ["Fluid velocity and flow regime.", "Fluid thermal properties and temperature.", "Surface geometry, orientation and roughness."], ["The selected correlation matches the geometry and regime.", "Properties are evaluated at the stated reference temperature.", "Radiation and conduction effects are separated or included appropriately."], ["Define fluid, geometry, surface temperature and bulk condition.", "Determine whether natural or forced convection applies.", "Obtain properties at an appropriate reference temperature.", "Select a correlation within its stated geometry and regime limits.", "Calculate h and combine it with other thermal resistances where required."], "A pipe carrying hot liquid loses heat to ambient air. Estimate the external convection coefficient from the actual orientation and airflow, then combine it with wall and insulation resistances rather than using h alone.", ["Heat-exchanger design screening.", "Cooling of equipment and electrical enclosures.", "Boiler and furnace heat-transfer studies.", "Process-heating and cooling estimates."], ["Treating h as a universal material constant.", "Using a correlation outside its geometry or flow range.", "Ignoring fouling, radiation or contact resistance.", "Using air properties at an unrelated temperature."], [["Is h a material property?", "No. It depends on the flow, geometry, surface and fluid condition."], ["Why is forced convection often higher?", "Higher fluid motion can thin the thermal boundary layer and increase heat transfer."], ["Can h be measured?", "It can be inferred from suitable tests and energy balances, subject to uncertainty."]], "thermal", "heat-transfer.html"),
  topic("ICH-ENG-021", "Thermal Engineering and Boilers", "Heat Transfer", "Radiation", "Thermal Radiation and Emissivity", "Thermal radiation is energy transfer by electromagnetic emission and absorption. It becomes especially important at high temperatures and depends on absolute temperature, surface emissivity, view and participating media.", "All surfaces emit thermal radiation. Net exchange depends on the temperatures, emissivities, areas, orientations and the extent to which one surface sees another or a surrounding enclosure.", [["Stefan-Boltzmann relation", "E = εσT⁴", "Emissive power depends on emissivity ε, Stefan-Boltzmann constant σ and absolute temperature T."], ["Simplified net exchange", "Q̇ ≈ εσA(Ts⁴ − Tsur⁴)", "A screening relation; real enclosures can require view factors and surface-resistance methods."]], [["Emissivity, ε", "Ratio of a surface’s emission to that of a blackbody at the same temperature."], ["Blackbody", "Ideal surface with emissivity of one."], ["View factor", "Geometric fraction of radiation leaving one surface that reaches another."], ["Absolute temperature", "Kelvin temperature required in radiation relations."]], ["Absolute temperatures of the exchanging surfaces.", "Surface emissivity, condition and oxidation.", "Geometry, view factors and intervening gases."], ["Surface properties are applicable at the stated temperature and wavelength context.", "The simplified exchange model suits the enclosure geometry.", "Radiation is combined with convection and conduction when all modes are relevant."], ["Define all exchanging surfaces and their temperatures.", "Use kelvin and identify emissivity data appropriate to the surface condition.", "Determine whether a simple ambient-surroundings model is defensible.", "Use view-factor and resistance methods for multi-surface enclosure work.", "Combine radiation with convection, conduction and any process heat sources."], "For a hot insulated surface in a workshop, radiation to surrounding walls may be significant. Compare the surface and surroundings in kelvin and assess radiation together with external convection.", ["Furnaces, boilers and fired heaters.", "High-temperature process equipment.", "Thermal insulation surface assessments.", "Solar and outdoor thermal studies."], ["Using Celsius in a T⁴ relation.", "Assuming emissivity is always one.", "Ignoring view factor in an enclosure.", "Treating radiation as negligible solely because air is present."], [["Why does radiation increase rapidly at high temperature?", "The emitted energy varies approximately with the fourth power of absolute temperature."], ["Does a shiny surface radiate less?", "Often, but actual emissivity depends on material, finish, oxidation and temperature."], ["Is radiation only important in a vacuum?", "No. It occurs through transparent gases and alongside convection and conduction."]], "thermal", "heat-transfer.html"),
  topic("ICH-ENG-022", "Thermal Engineering and Boilers", "Heat Transfer", "Overall Heat Transfer", "Overall Heat Transfer Coefficient", "The overall heat-transfer coefficient combines conduction, convection, fouling and contact resistances into one heat-transfer basis. It is used to connect a driving temperature difference with a heat duty.", "Heat passes through a series of thermal resistances. The smallest conductance or largest resistance can control the total rate; the chosen area basis must remain explicit when reporting U.", [["Overall heat-transfer relation", "Q̇ = U A ΔT", "Use a clearly defined area basis and an appropriate mean temperature difference."], ["Resistance form", "1/(UA) = ΣRthermal", "Sum convection, wall, fouling and contact resistances on a compatible basis."]], [["Overall coefficient, U", "Combined thermal conductance; SI unit W/(m²·K) on a stated area basis."], ["Fouling resistance", "Allowance for deposits that reduce heat transfer."], ["Area basis", "Inside, outside or another specified surface area."], ["Driving temperature difference", "Temperature difference selected for the actual heat-exchange arrangement."]], ["Individual film coefficients.", "Wall material, thickness and geometry.", "Fouling condition and selected area basis."], ["All resistances are converted to the same area basis.", "Temperatures and properties reflect operating conditions.", "The selected temperature-difference method matches flow arrangement."], ["Define duty, flow arrangement and all fluid conditions.", "Estimate or obtain inside and outside film coefficients.", "Add wall, fouling and contact resistances on one area basis.", "Calculate U and the applicable mean temperature difference.", "Check sensitivity to fouling, flow change and uncertainty."], "For a shell-and-tube exchanger, calculate tube-side film, wall, shell-side film and fouling resistances on one tube-area basis. The resulting U is then paired with an LMTD or other suitable driving temperature method.", ["Heat-exchanger performance estimates.", "Insulated-wall and jacketed-vessel studies.", "Boiler and condenser calculations.", "Thermal performance monitoring."], ["Reporting U without its area basis.", "Adding resistances expressed on different areas.", "Ignoring fouling for a service where deposits are expected.", "Using a simple temperature difference for a complex exchanger arrangement."], [["Is U a material property?", "No. It represents the complete heat-transfer path and operating condition."], ["Why is the area basis important?", "Inside and outside areas can differ, especially for tubes, so U changes with the chosen basis."], ["Can U be measured?", "It can be inferred from operating data when duty, temperatures and area are well defined."]], "thermal", "heat-transfer.html"),
  topic("ICH-ENG-024", "Thermal Engineering and Boilers", "Thermal Expansion and Insulation", "Insulation", "Industrial Insulation and Heat Loss Reduction", "Industrial insulation reduces unwanted heat transfer, protects personnel and stabilises process temperature. Its performance depends on material conductivity, thickness, installation quality, moisture condition and the full service environment.", "An insulation layer adds thermal resistance between a hot or cold surface and its surroundings. Heat loss or gain is determined by the complete resistance path, including convection, insulation, cladding, supports and thermal bridges.", [["Plane-wall resistance", "R = L/(kA)", "Thickness L and conductivity k determine the insulation conduction resistance."], ["One-dimensional heat rate", "Q̇ = ΔT / ΣRthermal", "Use a complete resistance network and consistent surface areas."], ["Cylindrical resistance", "R = ln(ro/ri)/(2πkL)", "Use cylindrical geometry for pipes and round vessels."]], [["Thermal conductivity, k", "Ability of a material to conduct heat; SI unit W/(m·K)."], ["Thermal bridge", "Path that bypasses insulation and increases local heat transfer."], ["Cladding", "Outer protective layer for weather and mechanical damage."], ["Surface temperature", "Temperature relevant to personnel protection and heat exchange."]], ["Operating temperature and temperature cycling.", "Insulation conductivity at service temperature.", "Moisture ingress, compression, gaps and thermal bridges."], ["Conductivity data suit the material, density and service temperature.", "Geometry and surface heat-transfer conditions are represented.", "Fire, corrosion-under-insulation and mechanical requirements are reviewed separately."], ["Define hot/cold service, ambient conditions and required performance objective.", "Select candidate insulation systems compatible with temperature and environment.", "Calculate heat transfer using appropriate geometry and surface coefficients.", "Review thickness, cladding, vapour barrier, supports and access details.", "Confirm fire, corrosion, personnel-protection and maintainability requirements."], "For a hot pipe, compare insulation thicknesses using cylindrical resistance and external surface conditions. Include weatherproofing and support details because gaps or wet insulation can invalidate an ideal calculation.", ["Process piping and vessels.", "Boilers, heaters and high-temperature equipment.", "Cold service and condensation control.", "Personnel-protection studies."], ["Using conductivity at room temperature only.", "Ignoring moisture or damaged cladding.", "Treating a flat-wall model as exact for a small pipe.", "Selecting insulation without fire, corrosion or access review."], [["Does thicker insulation always save proportionally more energy?", "It usually reduces conductive heat transfer, but benefits depend on geometry, surface conditions and project economics."], ["Why is wet insulation a concern?", "Moisture can degrade thermal performance and contribute to corrosion-under-insulation risks."], ["Is insulation selection only a heat-loss decision?", "No. Temperature, fire, mechanical, weather, corrosion and maintenance conditions matter."]], "thermal", "thermal-expansion.html"),
  topic("ICH-ENG-025", "Thermal Engineering and Boilers", "Heat Exchange Equipment", "Heat Exchanger Fundamentals", "Heat Exchanger Working Principle and Types", "A heat exchanger transfers energy between fluids at different temperatures while normally keeping their flow paths separated. Type, arrangement, materials, fouling, pressure drop and maintenance needs determine its suitability.", "Heat moves from the hotter fluid through a wall to the colder fluid by combined convection and conduction. The achievable duty depends on area, overall coefficient, temperature driving force and flow arrangement.", [["Heat duty", "Q̇ = ṁ cp ΔT", "Apply to each stream using a consistent flow and temperature basis."], ["Design relation", "Q̇ = U A ΔTlm F", "Use an appropriate log-mean temperature difference and correction factor where applicable."]], [["Hot and cold side", "The two process streams exchanging heat."], ["LMTD", "Log-mean temperature difference for a defined exchanger arrangement."], ["Fouling", "Deposits that add thermal resistance and pressure drop."], ["Approach temperature", "Temperature difference between streams at a selected end."]], ["Fluid properties, phase change and fouling tendency.", "Flow arrangement, heat duty and allowable temperature approach.", "Pressure drop, cleanability, materials and maintenance access."], ["The selected type is suitable for pressure, temperature and fluid compatibility.", "Heat duty is balanced between streams within stated loss assumptions.", "Vendor thermal and mechanical design is required for final equipment selection."], ["Define process streams, duty, temperatures, pressures and fouling basis.", "Screen exchanger types for compatibility, cleanability and layout.", "Estimate U, driving temperature and required area with a valid method.", "Check pressure drop, velocity, phase change and control requirements.", "Obtain vendor data and complete mechanical, materials and safety review."], "For a cooling duty, establish the process temperature change and utility inlet condition, calculate an initial duty, then compare shell-and-tube and plate options with their fouling, pressure-drop, maintenance and materials constraints.", ["Process heating and cooling.", "Condensers, evaporators and utility exchangers.", "Boiler feedwater and heat-recovery systems.", "Oil coolers and jacketed equipment."], ["Selecting by duty alone without pressure-drop and fouling review.", "Using an LMTD arrangement that does not match the exchanger.", "Ignoring phase change, corrosion or cleaning access.", "Treating an initial area estimate as a final vendor design."], [["What separates the fluids?", "A heat-transfer wall, unless the selected equipment intentionally mixes streams."], ["Which exchanger type is best?", "The correct type depends on duty, fluids, fouling, pressure, temperature, space and maintenance needs."], ["Why is fouling important?", "It reduces heat transfer and can increase pressure drop over time."]], "thermal", "heat-transfer.html")
];

