function pageHtml(p) {
  const prefix = href(p.route, "index.html").replace(/index\.html$/, "");
  const parentHref = href(p.route, p.parent);
  const l2Route = p.family === "fluid" ? fluidL2 : thermalL2;
  const l2Href = href(p.route, l2Route);
  const calculatorHref = href(p.route, p.calculator);
  const peer = pages.find((item) => item !== p && item.family === p.family && item.l3 === p.l3) || pages.find((item) => item !== p && item.family === p.family);
  const peerHref = href(p.route, peer.route);
  const asset = href(p.route, p.image);
  const references = bookSets[p.family].map((item) => `<li>${item}</li>`).join("");
  const definitionList = p.terms.map(([term, definition]) => `<div><dt>${esc(term)}</dt><dd>${esc(definition)}</dd></div>`).join("");
  const factorCards = p.factors.map((factor, i) => `<section><h3>${["Primary factor", "Service factor", "System factor"][i]}</h3><p>${esc(factor)}</p></section>`).join("");
  const formulas = p.formulae.map(([name, equation, note]) => `<section class="formula-card"><h3>${esc(name)}</h3><p class="formula-card__equation">${esc(equation)}</p><p>${esc(note)}</p></section>`).join("");
  const faqs = p.faqs.map(([q, a]) => `<details><summary>${esc(q)}</summary><p>${esc(a)}</p></details>`).join("");
  const related = [[p.l2, l2Href, "Parent Engineering collection"], [p.l3, parentHref, "Related topic collection"], [peer.title, peerHref, "Related knowledge page"], ["Relevant calculator", calculatorHref, "Existing engineering tool"], ["Engineering Knowledge Library", href(p.route, "index.html#knowledge-library-title"), "All published knowledge pages"]].map(([title, url, detail], i) => `<a class="related-knowledge-link" href="${url}"><span class="related-knowledge-link__icon" aria-hidden="true">${String(i + 1).padStart(2, "0")}</span><span><strong>${esc(title)}</strong><small>${esc(detail)}</small></span></a>`).join("");
  return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>${esc(p.title)} | Industrial Calculation Hub</title><meta name="description" content="${esc(p.summary)}"><meta name="robots" content="index,follow"><link rel="canonical" href="${canonical(p.route)}"><link rel="icon" type="image/svg+xml" href="${prefix}assets/brand/industrial-calculation-hub-mark.svg?v=20260824-colors"><link rel="alternate icon" href="${prefix}favicon.png"><link rel="stylesheet" href="${prefix}style.css?v=20260830-final-knowledge"><script type="application/ld+json">${JSON.stringify({"@context":"https://schema.org","@type":"Article",headline:p.title,description:p.summary,mainEntityOfPage:canonical(p.route),isPartOf:{"@type":"WebSite",name:"Industrial Calculation Hub",url:siteUrl},dateModified:"2026-08-30"})}</script><script defer src="${prefix}assets/js/site-search.js?v=20260830-next-15"></script></head><body class="public-page"><div class="site-frame"><header class="public-header"><a class="brand" href="${prefix}index.html" aria-label="Industrial Calculation Hub home"><img class="brand__mark" src="${prefix}assets/brand/industrial-calculation-hub-mark.svg?v=20260824-colors" alt=""><span class="brand__name"><strong>Industrial</strong><span>Calculation Hub</span></span></a><button class="public-menu-toggle" type="button" aria-expanded="false" aria-controls="public-navigation">Menu</button><nav class="public-nav" id="public-navigation" aria-label="Primary navigation" data-open="false"><a href="${prefix}index.html">Home</a><a href="${prefix}index.html#tools">Tools</a><a href="#article-content" aria-current="page">Learn</a><a href="${prefix}engineering-reference-data.html">Reference Data</a><a href="${prefix}about.html">About</a></nav><a class="header-search" href="#article-content" aria-label="Search topics, tools and articles"><span>Search topics, tools, articles...</span><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><circle cx="11" cy="11" r="6"/><path d="m16 16 5 5"/></svg></a></header><main class="knowledge-page" id="article-content"><article><header class="knowledge-page__hero"><div class="knowledge-page__hero-copy"><p class="domain-breadcrumb"><a href="${prefix}index.html">Home</a> <span aria-hidden="true">/</span> <a href="${prefix}engineering.html">Engineering</a> <span aria-hidden="true">/</span> <a href="${l2Href}">${esc(p.l2)}</a> <span aria-hidden="true">/</span> <a href="${parentHref}">${esc(p.l3)}</a> <span aria-hidden="true">/</span> ${esc(p.l4)}</p><p class="portal-kicker">Engineering principle</p><h1>${esc(p.title)}</h1><p class="knowledge-page__summary">${esc(p.summary)}</p></div><figure class="knowledge-page__hero-art"><img src="${asset}" alt="Original blueprint illustration providing engineering context"><figcaption>Original site illustration used as engineering context; it is not a project drawing or design calculation.</figcaption></figure></header><section class="knowledge-page__information" aria-label="Page information"><dl><div><dt>Content type</dt><dd>Engineering principle</dd></div><div><dt>Level</dt><dd>Engineering › ${esc(p.l2)} › ${esc(p.l3)} › ${esc(p.l4)} › ${esc(p.title)}</dd></div><div><dt>Audience</dt><dd>Student · Design engineer · Project engineer · Plant engineer</dd></div><div><dt>Last reviewed</dt><dd>${reviewDate}</dd></div></dl></section><div class="knowledge-page__body"><aside class="article-toc" aria-label="On this page"><p>On this page</p><ol><li><a href="#what-is">What it is</a></li><li><a href="#importance">Why it matters</a></li><li><a href="#terms">Key terms</a></li><li><a href="#principle">Fundamental principle</a></li><li><a href="#formulae">Formulae and units</a></li><li><a href="#assumptions">Assumptions and limits</a></li><li><a href="#factors">Factors</a></li><li><a href="#method">Engineering method</a></li><li><a href="#example">Illustrative example</a></li><li><a href="#applications">Applications</a></li><li><a href="#mistakes">Common mistakes</a></li><li><a href="#faq">Frequently asked questions</a></li><li><a href="#related">Related resources</a></li><li><a href="#references">References</a></li></ol></aside><div class="knowledge-page__content"><section id="what-is"><h2>What Is ${esc(p.title)}?</h2><p>${esc(p.summary)}</p></section><section id="importance"><h2>Why Is It Important in Engineering?</h2><p>${esc(p.principle)}</p><div class="article-callout article-callout--note"><strong>Use the stated basis.</strong><span>Identify the actual fluid, material, geometry, operating condition and relevant equipment boundary before using any engineering relation or reference value.</span></div></section><section id="terms"><h2>Key Terms and Definitions</h2><dl class="definition-list">${definitionList}</dl></section><section id="principle"><h2>Fundamental Principle</h2><p>${esc(p.principle)}</p></section><section id="formulae"><h2>Formulae, Symbols and Units</h2><div class="formula-grid">${formulas}</div><h3>Unit consistency</h3><p>Use a single, declared unit system. Confirm that all dimensions, properties and temperatures refer to the same service condition before combining them in a calculation.</p></section><section id="assumptions"><h2>Assumptions and Validity Range</h2>${list(p.assumptions)}</section><section id="factors"><h2>Factors Affecting the Result</h2><div class="article-card-grid">${factorCards}</div></section><section id="method"><h2>Step-by-Step Engineering Method</h2><ol class="method-list">${p.method.map((item) => `<li>${esc(item)}</li>`).join("")}</ol></section><section id="example"><h2>Illustrative Engineering Example</h2><div class="example-card"><p class="portal-kicker">Hypothetical example — not a design calculation</p><p>${esc(p.example)}</p><p>Use project data, applicable standards, supplier information and qualified review before making a design, procurement, construction or operating decision.</p></div></section><section id="applications"><h2>Industrial Applications</h2>${list(p.apps)}</section><section id="mistakes"><h2>Common Mistakes and Limitations</h2><div class="article-callout article-callout--warning"><strong>Do not extend a preliminary relation beyond its basis.</strong><span>Published equations and screening methods need appropriate geometry, operating data, source limits and independent engineering review for actual project use.</span></div>${list(p.mistakes)}</section><section id="faq"><h2>Frequently Asked Questions</h2><div class="faq-list">${faqs}</div></section><section id="related" class="related-knowledge-section"><h2>Related Engineering Resources</h2><p>These links lead to published, directly relevant resources in the approved site structure.</p><div class="related-knowledge-grid">${related}</div></section><section id="references"><h2>References</h2><ol class="references-list">${references}</ol><p class="references-note">This is an original educational summary. It does not reproduce protected book text, tables, figures or standards material.</p></section><section id="review"><h2>Review Information</h2><div class="review-panel"><strong>Final page-format review completed: ${reviewDate}.</strong><span>Content type: Engineering principle. This check confirms approved page structure, source listing, related-link scope and stated limitations. Independent qualified-engineer review remains required before project use.</span></div></section><section id="disclaimer"><h2>Engineering Disclaimer</h2><div class="disclaimer-panel"><strong>Educational and preliminary reference only.</strong><span>This page does not replace project specifications, detailed design, manufacturer information, applicable standards, safety requirements or review by a qualified engineer. Verify all values, assumptions and decisions for the actual service conditions.</span></div></section></div></div></article></main><footer class="site-footer"><nav class="footer-nav" aria-label="Legal and support navigation"><a href="${prefix}index.html">Home</a><a href="${prefix}about.html">About</a><a href="${prefix}contact.html">Contact</a><a href="${prefix}privacy.html">Privacy</a><a href="${prefix}disclaimer.html">Disclaimer</a><a href="${prefix}terms.html">Terms</a></nav><div class="footer-copyright">© 2026 Industrial Calculation Hub. All Rights Reserved.</div></footer></div><script>const menu=document.querySelector('.public-menu-toggle');const navigation=document.querySelector('.public-nav');menu?.addEventListener('click',()=>{const open=navigation.dataset.open==='true';navigation.dataset.open=String(!open);menu.setAttribute('aria-expanded',String(!open));});</script></body></html>`;
}

function updateSearch() {
  const searchFile = path.join(root, "assets", "js", "site-search.js");
  let source = fs.readFileSync(searchFile, "utf8");
  const match = source.match(/const staticSiteSearchIndex = (\[[\s\S]*?\]);\n\n  \/\//);
  if (!match) throw new Error("Cannot locate the static search index.");
  const index = JSON.parse(match[1]);
  pages.forEach((p) => { const item = index.find((entry) => entry.href === p.route); const record = { title: `${p.title} | Industrial Calculation Hub`, href: p.route, description: p.summary, type: "Engineering knowledge" }; if (item) Object.assign(item, record); else index.push(record); });
  fs.writeFileSync(searchFile, source.replace(match[1], JSON.stringify(index)));
}

function updateHome() {
  const indexFile = path.join(root, "index.html"); let source = fs.readFileSync(indexFile, "utf8");
  const missingPages = pages.filter((p) => !source.includes(`href="${p.route}"`));
  const cards = missingPages.map((p) => `<a href="${p.route}"><span>${p.family === "fluid" ? "Fluid mechanics" : "Thermal engineering"}</span><strong>${esc(p.title)}</strong><small>${esc(p.summary.split(". ")[0])}</small></a>`).join("\n            ");
  const marker = "          </div>\n        </section>\n        <div class=\"portal-bottom-grid\">";
  if (!source.includes(marker)) throw new Error("Cannot locate homepage knowledge-library end.");
  if (cards) source = source.replace(marker, `            ${cards}\n${marker}`);
  source = source.replace("Explore all fifteen established engineering articles. Each page now uses the current reading, search and navigation format.", "Explore all published engineering articles. Each page uses the current reading, search and navigation format.");
  fs.writeFileSync(indexFile, source);
}

function promoteParentCards() {
  const firstByL4 = new Map(); pages.forEach((p) => { if (!firstByL4.has(`${p.parent}|${p.l4}`)) firstByL4.set(`${p.parent}|${p.l4}`, p); });
  for (const p of firstByL4.values()) {
    const filename = file(p.parent); let source = fs.readFileSync(filename, "utf8"); const relative = href(p.parent, p.route); const cardTitle = p.cardTitle || p.l4; const escaped = cardTitle.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
    if (source.includes(`href="${relative}"`)) continue;
    const expression = new RegExp(`<article class="discipline-card"><span class="discipline-card__number">([^<]+)</span><h3>${escaped}</h3>[\\s\\S]*?</article>`);
    if (!expression.test(source)) throw new Error(`Cannot promote parent card: ${p.parent} :: ${p.l4}`);
    source = source.replace(expression, `<a class="discipline-card discipline-card--link" href="${relative}"><span class="discipline-card__number">$1</span><h3>${esc(cardTitle)}</h3><p>${esc(p.title)} is now available as a final knowledge page.</p><span class="discipline-card__status">Read guide →</span></a>`);
    source = source.replace("These Level 4 routes are shown for orientation. They are not published as working links until their knowledge content is complete and technically reviewed.", "Published Level 4 knowledge pages are available as working links. Remaining routes are shown for orientation until their knowledge content is complete and reviewed.");
    fs.writeFileSync(filename, source);
  }
}

function updateSitemap() {
  const sitemap = path.join(root, "sitemap.xml"); let source = fs.readFileSync(sitemap, "utf8");
  const additions = pages.filter((p) => !source.includes(canonical(p.route))).map((p) => `<url>\n    <loc>${canonical(p.route)}</loc>\n    <changefreq>monthly</changefreq>\n    <priority>0.7</priority>\n</url>`).join("\n\n");
  if (additions) source = source.replace("\n</urlset>", `\n${additions}\n\n</urlset>`); fs.writeFileSync(sitemap, source);
}

function updateStatus() {
  const status = path.join(root, "SITE-STATUS.md"); let source = fs.readFileSync(status, "utf8");
  source = source.replace("| Published engineering knowledge pages | Final page-format rewrite and formal format/source review complete | 16 |", "| Published engineering knowledge pages | Final page-format rewrite and formal format/source review complete | 31 |");
  source = source.replace("All fifteen legacy root knowledge articles plus `Density, Specific Gravity and Specific Weight` now use", "All sixteen previous knowledge pages plus fifteen further Engineering pages now use");
  source = source.replace("| New knowledge pages from frozen hierarchy | In progress | 16 |", "| New knowledge pages from frozen hierarchy | In progress | 31 |");
  source = source.replace("The 16 established knowledge pages are now complete", "Thirty-one knowledge pages are now complete");
  fs.writeFileSync(status, source);
}

function writeReview() {
  const out = path.join(root, "outputs", "NEXT-15-ENGINEERING-KNOWLEDGE-REVIEW.md");
  const rows = pages.map((p, i) => `| ${String(i + 1).padStart(2, "0")} | ${p.id} | ${p.title} | /${p.route.replace(/index\.html$/, "")} | ${p.l3} | Pass — final format, source and internal-link review |`).join("\n");
  fs.writeFileSync(out, `# Next 15 Engineering Knowledge Pages — Review\n\nReview date: ${reviewDate}\n\nThis review confirms that the 15 selected frozen Engineering records were created at one canonical route each, use the final knowledge-page format, and are linked from the homepage library, search index, sitemap and relevant parent Level 3 collection. It is not an independent qualified-engineer certification or project-use approval.\n\n| # | Content ID | Page title | Canonical route | Parent collection | Review result |\n| ---: | --- | --- | --- | --- | --- |\n${rows}\n\nIndependent qualified-engineer review remains required before project use.\n`);
}

function validate() {
  const issues = [];
  pages.forEach((p) => { const source = fs.readFileSync(file(p.route), "utf8"); ["knowledge-page__information", "article-toc", "Frequently Asked Questions", "Related Engineering Resources", "Review Information", "Engineering Disclaimer", `<link rel=\"canonical\" href=\"${canonical(p.route)}\">`].forEach((required) => { if (!source.includes(required)) issues.push(`${p.route}: missing ${required}`); }); [...source.matchAll(/(?:href|src)="([^"]+)"/g)].map((match) => match[1]).filter((value) => value && !value.startsWith("#") && !value.startsWith("http") && !value.startsWith("mailto:")).forEach((value) => { const target = path.resolve(path.dirname(file(p.route)), value.split(/[?#]/)[0]); if (!fs.existsSync(target) && !fs.existsSync(path.join(target, "index.html"))) issues.push(`${p.route}: broken local target ${value}`); }); });
  const home = fs.readFileSync(path.join(root, "index.html"), "utf8"); pages.forEach((p) => { if (!home.includes(`href="${p.route}"`)) issues.push(`homepage missing ${p.route}`); });
  if (issues.length) throw new Error(`Validation failed:\n${issues.join("\n")}`);
}

if (pages.length !== 15) throw new Error(`Expected 15 pages, found ${pages.length}.`);
pages.forEach((p) => { fs.mkdirSync(path.dirname(file(p.route)), { recursive: true }); fs.writeFileSync(file(p.route), pageHtml(p)); });
updateSearch(); updateHome(); promoteParentCards(); updateSitemap(); updateStatus(); validate(); writeReview(); console.log(`Created, linked and validated ${pages.length} Engineering knowledge pages.`);
